import java.io.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) return -1;
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        int[] values = new int[n];
        boolean[] present = new boolean[1000001];
        for (int i = 0; i < n; i++) {
            values[i] = nextInt();
            present[values[i]] = true;
        }
        int best = 1;
        // Extend a chain from every start by repeated squaring while the square is present.
        for (int start : values) {
            long v = start;
            int length = 1;
            while (v <= 1000 && present[(int) (v * v)]) {
                v *= v;
                length++;
            }
            best = Math.max(best, length);
        }
        System.out.println(best >= 2 ? best : -1);
    }
}

package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

func nextInt() int64 {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(bufio.NewReader(os.Stdin))
	n := int(nextInt())
	values := make([]int64, n)
	present := make([]bool, 1000001)
	for i := range values {
		values[i] = nextInt()
		present[values[i]] = true
	}
	best := 1
	// Extend a chain from every start by repeated squaring while the square is present.
	for _, start := range values {
		v, length := start, 1
		for v <= 1000 && present[v*v] {
			v *= v
			length++
		}
		best = max(best, length)
	}
	if best < 2 {
		best = -1
	}
	fmt.Println(best)
